package ep.model;

/**
 * The two kinds of entries that can appear on the calendar.
 */
public enum ItemType {
    /** A fixed commitment entered by the student. Never moved by the program. */
    EVENT("Fixed event"),
    /** A study block generated by the planner for an assignment. */
    STUDY_BLOCK("Study block");

    private final String label;

    ItemType(String label) {
        this.label = label;
    }

    /** @return a human readable label */
    public String getLabel() {
        return label;
    }

    @Override
    public String toString() {
        return label;
    }
}
